const item = $input.first().json;

// Retrieve raw HTML from the upstream Check HTTP Error node
const rawHtml = item.data || '';

function cleanHtmlToText(html) {
  if (!html || typeof html !== 'string') return '';
  return html
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, ' ')
    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, ' ')
    .replace(/<svg\b[^<]*(?:(?!<\/svg>)<[^<]*)*<\/svg>/gi, ' ')
    .replace(/<noscript\b[^<]*(?:(?!<\/noscript>)<[^<]*)*<\/noscript>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 12000); // Truncate to avoid context window overflow
}

const plainText = cleanHtmlToText(rawHtml);

// Resolve domain and canonical URL using valid JavaScript OR (||)
// Resolve plain text from whatever input fed this node
const domain = item.domain || item.candidate_domain || '';
const url = item.candidate_url || item.url || (domain ? `https://${domain}` : '');

return [{
  json: {
    domain: domain,
    url: url,
    website_text: plainText
  }
}];

