// Retrieve the raw input from the form trigger
const item = $input.first().json;

// Check 'Company Input' from the form trigger, plus standard fallback keys
const rawInput = (
  item['Company Input'] ||
  item.query ||
  item.company_name ||
  item.domain ||
  ''
).trim();

// Domain detection regex / check
const isDomain = /^([a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}(\/.*)?$/.test(rawInput) || rawInput.startsWith('http');

if (isDomain) {
  let cleanDomain = rawInput.replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0].toLowerCase();
  return {
    json: {
      input_type: 'domain',
      raw_input: rawInput,
      candidate_domain: cleanDomain,
      candidate_url: `https://${cleanDomain}`
    }
  };
} else {
  return {
    json: {
      input_type: 'name',
      raw_input: rawInput,
      company_name: rawInput
    }
  };
}

const items = $input.all();
const query = $('Normalize Input').first().json.company_name?.toLowerCase().trim() || '';

// High-profile non-company domains to reject
const ignoredDomains = [
  'linkedin.com', 'twitter.com', 'x.com', 'facebook.com', 'instagram.com',
  'crunchbase.com', 'bloomberg.com', 'wikipedia.org', 'pitchbook.com',
  'glassdoor.com', 'indeed.com', 'youtube.com', 'zoominfo.com'
];

function extractDomain(inputUrl) {
  if (!inputUrl) return '';
  try {
    const parsed = new URL(inputUrl.startsWith('http') ? inputUrl : 'https://' + inputUrl);
    return parsed.hostname.replace(/^www\./, '');
  } catch (e) {
    return inputUrl.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].trim();
  }
}

const candidates = [];

for (const item of items) {
  const url = item.json.url || '';
  const title = (item.json.title || '').toLowerCase();
  let hostname = '';

  try {
    hostname = new URL(url).hostname.replace(/^www\./, '');
  } catch (e) {
    continue;
  }

  // Filter out social, directory, and media platforms
  if (ignoredDomains.some(d => hostname.endsWith(d))) continue;

  let score = 0;
  const cleanName = query.replace(/[^a-z0-9]/g, '');
  const cleanHost = hostname.split('.')[0].replace(/[^a-z0-9]/g, '');

  if (cleanHost === cleanName) score += 50;
  else if (cleanHost.includes(cleanName) || cleanName.includes(cleanHost)) score += 30;
  if (title.includes(query)) score += 25;

  candidates.push({
    domain: hostname,
    url: url,
    title: item.json.title,
    score: score
  });
}

candidates.sort((a, b) => b.score - a.score);

// Fallback to the top candidate directly without a hard cutoff
if (candidates.length > 0 && (candidates[0].domain || candidates[0].url)) {
  const topMatch = candidates[0];
  const domain = extractDomain(topMatch.domain || topMatch.url);
  return [{
    json: {
      status: 'resolved',
      candidate_domain: domain,
      candidate_url: topMatch.url?.startsWith('http') ? topMatch.url : `https://${domain}`,
      confidence: topMatch.score || 0
    }
  }];
}

const firstRaw = items[0]?.json;
const rawUrl = firstRaw?.url || firstRaw?.id || '';
const cleanDomain = extractDomain(rawUrl);

return [{
  json: {
    status: 'resolved',
    candidate_domain: cleanDomain,
    candidate_url: rawUrl.startsWith('http') ? rawUrl : (cleanDomain ? `https://${cleanDomain}` : ''),
    confidence: 0
  }
}];

