// Example of how to structure the Exa results array for your LLM prompt
const exaResults = $('Find Growth Signals').all().map(item => {
  return `
- Title: ${item.json.title || 'N/A'}
  URL: ${item.json.url || 'N/A'}
  Published Date: ${item.json.publishedDate || 'Unknown'}
  Summary: ${item.json.summary || item.json.text || 'No summary available.'}
  `;
}).join('\n');

return [{
  json: {
    ...$json,
    formatted_exa_evidence: exaResults
  }
}];

const raw = $('Synthesize Intelligence & Evidence').first().json.output?.[0]?.content?.[0]?.text || '';

let synthesis = {};
try {
  const cleaned = raw.replace(/```json\s?|```/g, '').trim();
  const jsonStart = cleaned.indexOf('{');
  const jsonEnd = cleaned.lastIndexOf('}');
  synthesis = JSON.parse(cleaned.substring(jsonStart, jsonEnd + 1));
} catch (error) {
  return [{
    json: {
      ...$json,
      icp_score: null,
      icp_tier: 'Needs Review',
      scoring_rationale: ['Research synthesis was not valid JSON']
    }
  }];
}

const summary = String(synthesis.summary || '').toLowerCase();
const facts = JSON.stringify(synthesis.confirmed_facts || []).toLowerCase();
const combinedText = summary + ' ' + facts;

let score = 20; // Lower, more honest baseline
const reasons = [];

// 1. Core Target Vertical (Up to +35 pts)
if (/saas|software|technology/i.test(combinedText)) {
  score += 35;
  reasons.push('Core vertical: SaaS/Technology (+35)');
} else if (/manufacturing|industrial|supplier|logistics/i.test(combinedText)) {
  score += 30;
  reasons.push('Target vertical: Manufacturing/Industrial/Logistics (+30)');
} else {
  reasons.push('Standard vertical (+0)');
}

// 2. Technical Stack & Workflow Need (Up to +25 pts)
if (/workflow|automation|portal|integration|custom software/i.test(combinedText)) {
  score += 25;
  reasons.push('Strong technical/workflow alignment (+25)');
}

// 3. Growth & Scale Signals (Up to +20 pts)
if (/growth|expanding|hiring|partnership|funding|acquisition/i.test(combinedText)) {
  score += 20;
  reasons.push('Active growth signals detected (+20)');
}

score = Math.min(Math.max(score, 0), 100);

let tier = 'Low Fit';
if (score >= 80) {
  tier = 'High Fit';
} else if (score >= 55) {
  tier = 'Moderate Fit';
}

// Sanitize account brief starting line
let rawBrief = $json.account_brief || '';
if (rawBrief) {
  rawBrief = rawBrief.replace(/^(#+\s*|\*\*)/gm, '').replace(/\*\*$/, '').trim();
  if (!rawBrief.toLowerCase().startsWith('account brief:')) {
    rawBrief = rawBrief.replace(/^company summary[:\s]*/i, '');
    rawBrief = `Account Brief: ${synthesis.company_name || 'Target Company'}\n\nCompany Summary\n${rawBrief}`;
  }
}

return [{
  json: {
    ...$json,
    icp_score: score,
    icp_tier: tier,
    scoring_rationale: reasons,
    parsed_synthesis: synthesis,
    account_brief: rawBrief || $json.account_brief
  }
}];
